import manifestJson from '../data/generated/spine-manifest.json';
import { SpineManifestSchema, type ManifestStructure } from '../data/schema';

/**
 * Spine section data, generated by pipeline/spine_segment.py + spine_build.py from one whole-spine CT (VerSe
 * sub-verse823, CC BY-SA 4.0) and TotalSegmentator segmentations of it. Coordinates: RAS mm from the centre of the L5 vertebral body.
 */
export const SP_MANIFEST = SpineManifestSchema.parse(manifestJson);
export const SP = new Map(SP_MANIFEST.structures.map((s) => [s.id, s]));
/** Content references with a short label ('uribe2010' -> 'Uribe 2010'), for the cards' source links. */
const REF_LABELS: Record<string, string> = {
  isncsci2019: 'ISNCSCI 2019', moncadahabib2025: 'Moncada-Habib 2025', wangr2021: 'Wang 2021', lehmankuklo2003: 'Lehman & Kuklo 2003',
  alicandri2020: 'Alicandri-Ciufelli 2020', valenzuela2026: 'Valenzuela-Fuenzalida 2026',
  aosurgeryref: 'AO Surgery Reference', gonzalezvargas2026: 'González-Vargas 2026', figa2025: 'Figà 2025',
};
export const SP_REFS = new Map(Object.entries(SP_MANIFEST.references).map(([k, r]) => {
  const m = /^([a-z]+)(\d{4})$/.exec(k);
  const label = REF_LABELS[k] ?? (m ? `${m[1][0].toUpperCase()}${m[1].slice(1)} ${m[2]}` : k);
  return [k, { ...r, shortLabel: label }];
}));

export type RegionId = 'cervical' | 'thoracic' | 'lumbar' | 'ccj';
export const LEVEL_ORDER = [...Array.from({ length: 7 }, (_, i) => `C${i + 1}`), ...Array.from({ length: 12 }, (_, i) => `T${i + 1}`),
  ...Array.from({ length: 5 }, (_, i) => `L${i + 1}`), 'S1'];

/** The vertebra (or sacrum) structure of a level. */
export function vertebraOf(level: string): ManifestStructure | undefined {
  return level === 'S1' ? SP.get('sp_sacrum') : SP.get(`sp_${level.toLowerCase()}`);
}
/** The disc below a level ('L4' -> 'L4-L5'), if the model has it. */
export function discBelow(level: string): ManifestStructure | undefined {
  const i = LEVEL_ORDER.indexOf(level);
  const next = LEVEL_ORDER[i + 1];
  return next ? SP.get(`sp_disc_${level.toLowerCase()}_${next.toLowerCase()}`) : undefined;
}

/** Cross-checks between the generated files. Returns a list of problems (empty = consistent). */
export function crossCheckSpine(): string[] {
  const errs: string[] = [];
  for (const s of SP_MANIFEST.structures) {
    if (s.category === 'vertebra' && !s.level) errs.push(`${s.id}: vertebra without a level`);
    if (s.category === 'disc' && !(s.level && /^[CTL]\d+-[CTLS]\d+$/.test(s.level))) errs.push(`${s.id}: disc level ${s.level}`);
  }
  for (const lv of ['L1', 'L2', 'L3', 'L4', 'L5', 'S1']) if (!vertebraOf(lv)) errs.push(`no structure for ${lv}`);
  return errs;
}
